mapper.select:
select

from FIN_PRODUCT_SPPI_INFO
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and BRANCH = #{branch,jdbcType=DECIMAL}

mapper.delete:
delete from FIN_PRODUCT_SPPI_INFO
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and BRANCH = #{branch,jdbcType=DECIMAL}

mapper.update:
update FIN_PRODUCT_SPPI_INFO
set TEST_DATE = #{testDate,jdbcType=DATE},
    TEST_RESULT = #{testResult,jdbcType=VARCHAR},
    REMARK = #{remark,jdbcType=VARCHAR},
    UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and BRANCH = #{branch,jdbcType=DECIMAL}
